function animate() {
  if (!window.gsap || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const mm = gsap.matchMedia();
  mm.add({ reduce: '(prefers-reduced-motion: reduce)', desktop: '(min-width: 761px)' }, context => {
    if (context.conditions.reduce) return;
    const intro = gsap.timeline({ defaults: { ease: 'power3.out' } });
    intro.from('.nav>*', { autoAlpha: 0, y: -12, duration: .45, stagger: .06 })
      .from('.hero-meta>*', { autoAlpha: 0, y: 14, duration: .45, stagger: .08 }, .12)
      .from('.hero h1', { autoAlpha: 0, y: 48, duration: 1 }, .22)
      .from('.hero-title p,.hero-bottom', { autoAlpha: 0, y: 18, duration: .65, stagger: .08 }, .42)
      .to('.cover-frame i', { scaleX: 0, duration: 1.1, ease: 'power4.inOut' }, .35);
    const seen = new IntersectionObserver(entries => entries.forEach(entry => { if (!entry.isIntersecting) return; const el = entry.target; gsap.from(el, { autoAlpha: 0, y: 24, duration: .7, ease: 'power3.out', overwrite: 'auto' }); if (el.dataset.animate === 'scene') gsap.from(el.querySelectorAll('figure'), { autoAlpha: 0, y: 28, duration: .7, stagger: .12, ease: 'power3.out', overwrite: 'auto' }); if (el.dataset.animate === 'chapter') gsap.from(el.querySelector('i'), { scaleX: 0, duration: .9, ease: 'power2.out' }); seen.unobserve(el); }), { threshold: .14 });
    document.querySelectorAll('[data-animate]').forEach(el => { if (!['hero','cover'].includes(el.dataset.animate)) seen.observe(el); });
    document.querySelectorAll('.scene,.highlight,.closing>div a').forEach(el => { el.addEventListener('pointerenter', () => gsap.to(el, { y: -5, duration: .25, ease: 'power2.out', overwrite: 'auto' })); el.addEventListener('pointerleave', () => gsap.to(el, { y: 0, duration: .25, ease: 'power2.out', overwrite: 'auto' })); });
    return () => seen.disconnect();
  });
}
animate();
